const cache={};
// Each filled run becomes one rect, so icons stay crisp at any integer scale.
export function icon(id){if(cache[id])return cache[id];const b=bits[id]||bits.seed;let d='';for(let y=0;y<16;y++){let x=0;while(x<16){if(b[y*16+x]==='#'){let w=1;while(x+w<16&&b[y*16+x+w]==='#')w++;d+=`M${x} ${y}h${w}v1h-${w}z`;x+=w;}else x++;}}return cache[id]=`<svg viewBox="0 0 16 16" fill="currentColor" shape-rendering="crispEdges" aria-hidden="true"><path d="${d}"/></svg>`;}
